  1→<!DOCTYPE html>
  2→<html lang="zh-CN">
  3→<head>
  4→    <meta charset="UTF-8">
  5→    <meta name="viewport" content="width=device-width, initial-scale=1.0">
  6→    <title>登录</title>
  7→    <style>
  8→        :root {
  9→            --bg-color: #f5f5f7;
 10→            --bg-gradient: radial-gradient(circle at 50% 0%, #ffffff 0%, #f5f5f7 100%);
 11→            --card-bg: rgba(255, 255, 255, 0.8);
 12→            --card-border: rgba(255, 255, 255, 0.6);
 13→            --text-primary: #1d1d1f;
 14→            --text-secondary: #86868b;
 15→            --accent-color: #0071e3;
 16→            --accent-hover: #0077ed;
 17→            --error-color: #ff3b30;
 18→            --border-color: #d2d2d7;
 19→            --input-bg: #ffffff;
 20→            --focus-ring: rgba(0, 113, 227, 0.2);
 21→            --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.04);
 22→            --shadow-md: 0 8px 30px rgba(0, 0, 0, 0.08);
 23→        }
 24→
 25→        @media (prefers-color-scheme: dark) {
 26→            :root {
 27→                --bg-color: #000000;
 28→                --bg-gradient: radial-gradient(circle at 50% 0%, #1c1c1e 0%, #000000 100%);
 29→                --card-bg: rgba(28, 28, 30, 0.6);
 30→                --card-border: rgba(255, 255, 255, 0.1);
 31→                --text-primary: #f5f5f7;
 32→                --text-secondary: #86868b;
 33→                --accent-color: #0a84ff;
 34→                --accent-hover: #409cff;
 35→                --border-color: #38383a;
 36→                --input-bg: rgba(255, 255, 255, 0.05);
 37→                --focus-ring: rgba(10, 132, 255, 0.3);
 38→                --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.2);
 39→                --shadow-md: 0 8px 30px rgba(0, 0, 0, 0.4);
 40→            }
 41→        }
 42→
 43→        * {
 44→            box-sizing: border-box;
 45→            margin: 0;
 46→            padding: 0;
 47→        }
 48→
 49→        body {
 50→            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
 51→            background: var(--bg-gradient);
 52→            background-color: var(--bg-color);
 53→            color: var(--text-primary);
 54→            display: flex;
 55→            justify-content: center;
 56→            align-items: center;
 57→            min-height: 100vh;
 58→            padding: 20px;
 59→            line-height: 1.5;
 60→            -webkit-font-smoothing: antialiased;
 61→            -moz-osx-font-smoothing: grayscale;
 62→        }
 63→
 64→        .login-container {
 65→            width: 100%;
 66→            max-width: 400px;
 67→            background-color: var(--card-bg);
 68→            backdrop-filter: blur(20px);
 69→            -webkit-backdrop-filter: blur(20px);
 70→            border: 1px solid var(--card-border);
 71→            padding: 48px 40px;
 72→            border-radius: 24px;
 73→            box-shadow: var(--shadow-md);
 74→            transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.3s ease;
 75→        }
 76→
 77→        .login-container:hover {
 78→            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.12);
 79→        }
 80→
 81→        h1 {
 82→            font-size: 32px;
 83→            font-weight: 700;
 84→            text-align: center;
 85→            margin-bottom: 12px;
 86→            text-wrap: balance;
 87→            letter-spacing: -0.5px;
 88→            background: linear-gradient(135deg, var(--text-primary) 0%, #4a4a4c 100%);
 89→            -webkit-background-clip: text;
 90→            -webkit-text-fill-color: transparent;
 91→        }
 92→
 93→        @media (prefers-color-scheme: dark) {
 94→            h1 {
 95→                background: linear-gradient(135deg, #ffffff 0%, #a1a1a6 100%);
 96→                -webkit-background-clip: text;
 97→                -webkit-text-fill-color: transparent;
 98→            }
 99→        }
100→
101→        .subtitle {
102→            text-align: center;
103→            color: var(--text-secondary);
104→            font-size: 16px;
105→            margin-bottom: 40px;
106→            font-weight: 400;
107→        }
108→
109→        .form-group {
110→            margin-bottom: 20px;
111→            position: relative;
112→        }
113→
114→        label {
115→            display: block;
116→            font-size: 13px;
117→            font-weight: 500;
118→            margin-bottom: 8px;
119→            color: var(--text-primary);
120→        }
121→
122→        input {
123→            width: 100%;
124→            padding: 14px 16px;
125→            font-size: 16px;
126→            border: 1px solid var(--border-color);
127→            border-radius: 12px;
128→            background-color: var(--input-bg);
129→            color: var(--text-primary);
130→            transition: all 0.2s cubic-bezier(0.2, 0, 0, 1);
131→            outline: none;
132→        }
133→
134→        input::placeholder {
135→            color: var(--text-secondary);
136→            opacity: 0.6;
137→        }
138→
139→        input:hover {
140→            border-color: #86868b;
141→        }
142→
143→        @media (prefers-color-scheme: dark) {
144→            input:hover {
145→                border-color: #555;
146→            }
147→        }
148→
149→        input:focus-visible {
150→            border-color: var(--accent-color);
151→            box-shadow: 0 0 0 4px var(--focus-ring);
152→            background-color: var(--card-bg);
153→        }
154→
155→        input.error {
156→            border-color: var(--error-color);
157→            background-color: rgba(255, 59, 48, 0.05);
158→        }
159→
160→        .error-message {
161→            color: var(--error-color);
162→            font-size: 12px;
163→            margin-top: 6px;
164→            display: none;
165→        }
166→
167→        .error-message.visible {
168→            display: block;
169→        }
170→
171→        button[type="submit"] {
172→            width: 100%;
173→            padding: 14px;
174→            background: linear-gradient(135deg, var(--accent-color) 0%, var(--accent-hover) 100%);
175→            color: white;
176→            border: none;
177→            border-radius: 12px;
178→            font-size: 16px;
179→            font-weight: 600;
180→            cursor: pointer;
181→            transition: all 0.2s cubic-bezier(0.2, 0, 0, 1);
182→            margin-top: 8px;
183→            position: relative;
184→            box-shadow: 0 4px 12px rgba(0, 113, 227, 0.25);
185→            letter-spacing: 0.5px;
186→        }
187→
188→        button[type="submit"]:hover {
189→            transform: translateY(-1px);
190→            box-shadow: 0 6px 16px rgba(0, 113, 227, 0.35);
191→        }
192→
193→        button[type="submit"]:active {
194→            transform: translateY(0) scale(0.98);
195→            box-shadow: 0 2px 8px rgba(0, 113, 227, 0.2);
196→        }
197→
198→        button[type="submit"]:focus-visible {
199→            outline: none;
200→            box-shadow: 0 0 0 4px var(--focus-ring);
201→        }
202→
203→        button[type="submit"]:disabled {
204→            opacity: 0.7;
205→            cursor: not-allowed;
206→        }
207→
208→        .spinner {
209→            display: none;
210→            width: 20px;
211→            height: 20px;
212→            border: 2px solid rgba(255, 255, 255, 0.3);
213→            border-top-color: white;
214→            border-radius: 50%;
215→            animation: spin 0.8s linear infinite;
216→            position: absolute;
217→            right: 16px;
218→            top: 50%;
219→            transform: translateY(-50%);
220→        }
221→
222→        button[type="submit"].loading .spinner {
223→            display: block;
224→        }
225→
226→        button[type="submit"].loading {
227→            color: transparent;
228→        }
229→
230→        @keyframes spin {
231→            to { transform: translateY(-50%) rotate(360deg); }
232→        }
233→
234→        @media (prefers-reduced-motion: reduce) {
235→            * {
236→                animation-duration: 0.01ms !important;
237→                animation-iteration-count: 1 !important;
238→                transition-duration: 0.01ms !important;
239→                scroll-behavior: auto !important;
240→            }
241→        }
242→
243→        .footer-links {
244→            margin-top: 24px;
245→            text-align: center;
246→            font-size: 14px;
247→        }
248→
249→        .footer-links a {
250→            color: var(--accent-color);
251→            text-decoration: none;
252→            font-weight: 500;
253→        }
254→
255→        .footer-links a:hover {
256→            text-decoration: underline;
257→        }
258→
259→        .footer-links a:focus-visible {
260→            outline: 2px solid var(--accent-color);
261→            outline-offset: 2px;
262→            border-radius: 2px;
263→        }
264→    </style>
265→</head>
266→<body>
267→    <main class="login-container">
268→        <h1>欢迎回来</h1>
269→        <p class="subtitle">请输入您的账号信息以继续</p>
270→        
271→        <form id="loginForm" novalidate>
272→            <div class="form-group">
273→                <label for="email">电子邮箱</label>
274→                <input 
275→                    type="email" 
276→                    id="email" 
277→                    name="email" 
278→                    autocomplete="username" 
279→                    spellcheck="false"
280→                    placeholder="name@example.com…"
281→                    required
282→                    aria-describedby="email-error"
283→                >
284→                <div id="email-error" class="error-message" role="alert" aria-live="polite"></div>
285→            </div>
286→
287→            <div class="form-group">
288→                <label for="password">密码</label>
289→                <input 
290→                    type="password" 
291→                    id="password" 
292→                    name="password" 
293→                    autocomplete="current-password" 
294→                    placeholder="请输入密码…"
295→                    required
296→                    aria-describedby="password-error"
297→                >
298→                <div id="password-error" class="error-message" role="alert" aria-live="polite"></div>
299→            </div>
300→
301→            <button type="submit" id="submitBtn">
302→                登录
303→                <span class="spinner" aria-hidden="true"></span>
304→            </button>
305→        </form>
306→
307→        <div class="footer-links">
308→            <a href="/forgot-password">忘记密码？</a>
309→        </div>
310→    </main>
311→
312→    <script>
313→        const form = document.getElementById('loginForm');
314→        const emailInput = document.getElementById('email');
315→        const passwordInput = document.getElementById('password');
316→        const submitBtn = document.getElementById('submitBtn');
317→
318→        function showError(input, message) {
319→            const errorDiv = document.getElementById(input.id + '-error');
320→            input.classList.add('error');
321→            input.setAttribute('aria-invalid', 'true');
322→            errorDiv.textContent = message;
323→            errorDiv.classList.add('visible');
324→        }
325→
326→        function clearError(input) {
327→            const errorDiv = document.getElementById(input.id + '-error');
328→            input.classList.remove('error');
329→            input.removeAttribute('aria-invalid');
330→            errorDiv.textContent = '';
331→            errorDiv.classList.remove('visible');
332→        }
333→
334→        function validateEmail(email) {
335→            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
336→        }
337→
338→        form.addEventListener('submit', async (e) => {
339→            e.preventDefault();
340→            
341→            // Clear previous errors
342→            clearError(emailInput);
343→            clearError(passwordInput);
344→
345→            let hasError = false;
346→
347→            if (!emailInput.value) {
348→                showError(emailInput, '请输入电子邮箱地址');
349→                hasError = true;
350→            } else if (!validateEmail(emailInput.value)) {
351→                showError(emailInput, '请输入有效的电子邮箱地址');
352→                hasError = true;
353→            }
354→
355→            if (!passwordInput.value) {
356→                showError(passwordInput, '请输入密码');
357→                hasError = true;
358→            }
359→
360→            if (hasError) {
361→                // Focus first error field
362→                const firstError = form.querySelector('[aria-invalid="true"]');
363→                if (firstError) firstError.focus();
364→                return;
365→            }
366→
367→            // Simulate login request
368→            submitBtn.disabled = true;
369→            submitBtn.classList.add('loading');
370→            submitBtn.setAttribute('aria-busy', 'true');
371→
372→            try {
373→                await new Promise(resolve => setTimeout(resolve, 2000));
374→                // Success handling would go here
375→                alert('登录成功！');
376→            } catch (error) {
377→                showError(emailInput, '登录失败，请重试');
378→            } finally {
379→                submitBtn.disabled = false;
380→                submitBtn.classList.remove('loading');
381→                submitBtn.removeAttribute('aria-busy');
382→            }
383→        });
384→
385→        // Real-time validation clearing
386→        emailInput.addEventListener('input', () => {
387→            if (emailInput.classList.contains('error')) clearError(emailInput);
388→        });
389→
390→        passwordInput.addEventListener('input', () => {
391→            if (passwordInput.classList.contains('error')) clearError(passwordInput);
392→        });
393→    </script>
394→</body>
395→</html>

