   313→        const form = document.getElementById('loginForm');
   314→        const emailInput = document.getElementById('email');
   315→        const passwordInput = document.getElementById('password');
   316→        const submitBtn = document.getElementById('submitBtn');
   317→
   318→        function showError(input, message) {
   319→            const errorDiv = document.getElementById(input.id + '-error');
   320→            input.classList.add('error');
   321→            input.setAttribute('aria-invalid', 'true');
   322→            errorDiv.textContent = message;
